const ATTENDANCE_TREND_FOCUSES=['Point-Bearing Events','Call-Offs','Tardies','NCNS','Left Early','Suspended Days','Doctor-Note Covered','Corrective Thresholds','Positive Credits Earned'];
function attendanceTrendReportRange(){
  const end=isIsoDateKey(reportDateEnd)?reportDateEnd:pointSystemAsOf();
  const start=isIsoDateKey(reportDateStart)?reportDateStart:addDays(end,-89);
  const valid=start<=end,days=valid?dayDiff(start,end)+1:0;
  const previousEnd=valid?addDays(start,-1):'',previousStart=valid?addDays(previousEnd,-days+1):'';
  return {start,end,valid,days,previousStart,previousEnd};
}
function attendanceTrendEmptyMetrics(){return {activeEmployees:0,issueOccurrences:0,pointEvents:0,pointsCharged:0,calloffs:0,tardies:0,tardyUnder5:0,tardy5to14:0,tardy15plus:0,ncns:0,leftEarly:0,earlyClockIn:0,suspended:0,doctorCovered:0,correctiveTriggers:0,positiveCreditsEarned:0,positiveCreditAwards:0};}
function attendanceTrendEmployeeShift(emp){return String(emp&&emp.shift||'Unassigned');}
function attendanceTrendEmployeePool(shiftFilter=attendanceTrendShiftFilter){return (attendance.employees||[]).filter(emp=>shiftFilter==='All'||attendanceTrendEmployeeShift(emp)===shiftFilter);}
function attendanceTrendMetricsForRange(start,end,shiftFilter=attendanceTrendShiftFilter){
  const out=attendanceTrendEmptyMetrics();
  if(!isIsoDateKey(start)||!isIsoDateKey(end)||start>end)return out;
  const employees=attendanceTrendEmployeePool(shiftFilter);
  out.activeEmployees=employees.filter(emp=>!isArchivedAttendanceEmployee(emp)).length;
  for(const emp of employees){
    const snap=attendancePointSnapshot(emp.id,end);
    const issues=(snap.issues||[]).filter(i=>i.date>=start&&i.date<=end);
    for(const issue of issues){
      if(issue.medicalCovered&&!issue.medicalPrimary)continue;
      const code=String(issue.code||'');
      const gross=Number(issue.gross||0);
      out.issueOccurrences++;
      if(gross>0){out.pointEvents++;out.pointsCharged+=gross;}
      if(['CO','CO1','CO2'].includes(code))out.calloffs++;
      if(['T','T<5','T5-14','T15+','T>5'].includes(code)){
        out.tardies++;
        if(code==='T'||code==='T<5')out.tardyUnder5++;
        else if(code==='T5-14')out.tardy5to14++;
        else out.tardy15plus++;
      }
      if(code==='NCNS')out.ncns++;
      if(['LE','UE'].includes(code))out.leftEarly++;
      if(code==='EIA')out.earlyClockIn++;
      if(issue.medicalCovered&&issue.medicalPrimary)out.doctorCovered++;
    }
    out.suspended+=attendanceEventsForEmployee(emp.id).filter(e=>e.date>=start&&e.date<=end&&e.code==='SUS').length;
    const earned=(snap.earned||[]).filter(x=>x.date>=start&&x.date<=end);
    out.positiveCreditAwards+=earned.length;
    out.positiveCreditsEarned+=earned.reduce((sum,x)=>sum+Number(x.amount||0),0);
    const thresholdDates=new Set(issues.map(x=>x.date));
    for(const adjustment of (attendance.pointAdjustments||[]))if(String(adjustment.empId)===String(emp.id)&&adjustment.effectiveDate>=start&&adjustment.effectiveDate<=end)thresholdDates.add(adjustment.effectiveDate);
    for(const date of thresholdDates){
      const before=attendanceActionRank(attendancePointSnapshot(emp.id,addDays(date,-1)).level);
      const after=attendanceActionRank(attendancePointSnapshot(emp.id,date).level);
      if(after>before&&after>=attendanceActionRank('Notice'))out.correctiveTriggers++;
    }
  }
  out.pointsCharged=Number(out.pointsCharged.toFixed(2));
  out.positiveCreditsEarned=Number(out.positiveCreditsEarned.toFixed(2));
  return out;
}
function attendanceTrendFocusKey(){return {'Point-Bearing Events':'pointEvents','Call-Offs':'calloffs','Tardies':'tardies','NCNS':'ncns','Left Early':'leftEarly','Suspended Days':'suspended','Doctor-Note Covered':'doctorCovered','Corrective Thresholds':'correctiveTriggers','Positive Credits Earned':'positiveCreditsEarned'}[attendanceTrendFocus]||'pointEvents';}
function attendanceTrendFocusValue(metrics){return Number(metrics[attendanceTrendFocusKey()]||0);}
function attendanceTrendSignal(current,previous,currentDays=1,previousDays=1){
  const currentRate=Number(current||0)/Math.max(1,Number(currentDays)||1),previousRate=Number(previous||0)/Math.max(1,Number(previousDays)||1);
  const delta=Number((Number(current||0)-Number(previous||0)).toFixed(2));
  let label='Stable';
  if(Number(current||0)+Number(previous||0)>=3&&delta>=2&&currentRate>previousRate*1.2)label='Rising';
  else if(Number(current||0)+Number(previous||0)>=3&&delta<=-2&&currentRate<previousRate*0.8)label='Falling';
  const percent=previousRate?Math.round(((currentRate-previousRate)/previousRate)*100):(currentRate>0?100:0);
  return {label,delta,percent,currentRate,previousRate};
}
function attendanceTrendBucketKey(date){
  if(attendanceTrendGroupBy==='Month')return String(date).slice(0,7);
  const d=parseISO(date);d.setDate(d.getDate()-d.getDay());return toISO(d);
}
function attendanceTrendBuckets(range){
  const map=new Map();
  for(let d=parseISO(range.start);d<=parseISO(range.end);d.setDate(d.getDate()+1)){
    const date=toISO(d),key=attendanceTrendBucketKey(date);
    if(!map.has(key))map.set(key,{key,start:date,end:date});
    else map.get(key).end=date;
  }
  return [...map.values()].map(bucket=>{
    const metrics=attendanceTrendMetricsForRange(bucket.start,bucket.end);
    return {...bucket,label:attendanceTrendGroupBy==='Month'?new Date(bucket.start+'T00:00:00').toLocaleDateString(undefined,{month:'short',year:'numeric'}):`${fmt(bucket.start)} – ${fmt(bucket.end)}`,days:dayDiff(bucket.start,bucket.end)+1,metrics,focus:attendanceTrendFocusValue(metrics)};
  }).map((bucket,index,all)=>({...bucket,signal:index?attendanceTrendSignal(bucket.focus,all[index-1].focus,bucket.days,all[index-1].days):{label:'Baseline',delta:0,percent:0}}));
}
function attendanceTrendMeasureRows(current,previous,days){
  const measures=[['Point-Bearing Events','pointEvents'],['Points Charged Before Credits','pointsCharged'],['Call-Off Occurrences','calloffs'],['Tardies — Under 5','tardyUnder5'],['Tardies — 5–14','tardy5to14'],['Tardies — 15+','tardy15plus'],['No Call / No Show','ncns'],['Left Early','leftEarly'],['Early Clock-In Without Approval','earlyClockIn'],['Suspended Days','suspended'],['Doctor-Note-Covered Occurrences','doctorCovered'],['Corrective Thresholds Triggered','correctiveTriggers'],['Positive Credits Earned','positiveCreditsEarned']];
  return measures.map(([label,key])=>{const c=Number(current[key]||0),p=Number(previous[key]||0),signal=attendanceTrendSignal(c,p,days,days);return {label,key,current:c,previous:p,delta:Number((c-p).toFixed(2)),signal:signal.label};});
}
function attendanceTrendReportData(){
  const range=attendanceTrendReportRange();
  if(!range.valid)return {range,current:attendanceTrendEmptyMetrics(),previous:attendanceTrendEmptyMetrics(),signal:{label:'Stable',delta:0,percent:0},buckets:[],shiftRows:[],measureRows:[]};
  const current=attendanceTrendMetricsForRange(range.start,range.end),previous=attendanceTrendMetricsForRange(range.previousStart,range.previousEnd);
  const signal=attendanceTrendSignal(attendanceTrendFocusValue(current),attendanceTrendFocusValue(previous),range.days,range.days);
  const shifts=attendanceTrendShiftFilter==='All'?Array.from(new Set((attendance.employees||[]).map(attendanceTrendEmployeeShift))).sort():[attendanceTrendShiftFilter];
  const shiftRows=shifts.map(shift=>{const now=attendanceTrendMetricsForRange(range.start,range.end,shift),prior=attendanceTrendMetricsForRange(range.previousStart,range.previousEnd,shift);return {shift,now,prior,focus:attendanceTrendFocusValue(now),previousFocus:attendanceTrendFocusValue(prior),signal:attendanceTrendSignal(attendanceTrendFocusValue(now),attendanceTrendFocusValue(prior),range.days,range.days).label};}).sort((a,b)=>b.focus-a.focus||a.shift.localeCompare(b.shift));
  return {range,current,previous,signal,buckets:attendanceTrendBuckets(range),shiftRows,measureRows:attendanceTrendMeasureRows(current,previous,range.days)};
}
function attendanceTrendReportControlsHtml(){
  return `<div class="report-scope-controls report-specialized-controls"><div><label>Period Grouping</label><select onchange="attendanceTrendGroupBy=this.value"><option ${attendanceTrendGroupBy==='Week'?'selected':''}>Week</option><option ${attendanceTrendGroupBy==='Month'?'selected':''}>Month</option></select></div><div><label>Trend Focus</label><select onchange="attendanceTrendFocus=this.value">${ATTENDANCE_TREND_FOCUSES.map(x=>`<option ${attendanceTrendFocus===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="mini-note">Trend Focus controls the period-over-period pressure signal. All approved aggregate measures remain visible in the report.</div>`;
}
function reportAttendanceTrendRisk(autoPrint=false){
  const data=attendanceTrendReportData();if(!data.range.valid){toast('Report start date must be on or before the end date.');return;}
  const c=data.current,p=data.previous,s=data.signal;
  const direction=s.label==='Rising'?`increased by ${Math.abs(s.delta)}`:s.label==='Falling'?`decreased by ${Math.abs(s.delta)}`:`changed by ${s.delta}`;
  const trendRows=data.buckets.map(x=>[esc(x.label),x.metrics.pointEvents,x.metrics.pointsCharged,x.metrics.calloffs,x.metrics.tardyUnder5,x.metrics.tardy5to14,x.metrics.tardy15plus,x.metrics.ncns,x.metrics.leftEarly,x.metrics.suspended,x.metrics.doctorCovered,x.metrics.correctiveTriggers,x.metrics.positiveCreditsEarned,`<strong>${esc(x.signal.label)}</strong>`]);
  const shiftRows=data.shiftRows.map(x=>[esc(x.shift),x.now.activeEmployees,x.now.pointEvents,x.now.pointsCharged,x.now.calloffs,x.now.tardies,x.now.ncns,x.now.leftEarly,x.now.suspended,x.now.doctorCovered,x.now.correctiveTriggers,x.now.positiveCreditsEarned,x.focus,x.previousFocus,`<strong>${esc(x.signal)}</strong>`]);
  const measureRows=data.measureRows.map(x=>[esc(x.label),x.current,x.previous,x.delta,`<strong>${esc(x.signal)}</strong>`]);
  const body=`<div class="report-section report-compact"><div class="report-summary"><strong>Management Summary:</strong> The selected ${esc(attendanceTrendFocus)} signal is <strong>${esc(s.label)}</strong>; the measure ${esc(direction)} versus the immediately preceding ${data.range.days}-day period. Current scope contains ${c.pointEvents} point-bearing event(s), ${c.pointsCharged} point(s) charged before credits, ${c.calloffs} call-off occurrence(s), ${c.tardies} tardy occurrence(s), ${c.ncns} NCNS occurrence(s), and ${c.correctiveTriggers} corrective threshold crossing(s).</div><div class="report-method"><strong>Scope:</strong> ${esc(fmt(data.range.start))} through ${esc(fmt(data.range.end))} · Shift: ${esc(attendanceTrendShiftFilter)} · Grouped by ${esc(attendanceTrendGroupBy)} · Focus: ${esc(attendanceTrendFocus)}. Rising/Falling requires at least two events of movement, at least three combined observations, and a rate change greater than 20%; otherwise the signal is Stable. Shift attribution uses the employee's current Attendance assignment. Employee names and doctor-note details are excluded.</div></div><div class="report-section report-compact">${reportKpis([{label:'Pressure Signal',value:s.label},{label:'Point-Bearing Events',value:c.pointEvents},{label:'Points Charged',value:c.pointsCharged},{label:'Call-Offs',value:c.calloffs},{label:'Tardies',value:c.tardies},{label:'NCNS',value:c.ncns},{label:'Thresholds Triggered',value:c.correctiveTriggers},{label:'Positive Credits Earned',value:c.positiveCreditsEarned}])}</div><div class="report-section report-allow-break"><h2>Period Trend</h2>${reportTable(['Period','Point Events','Points Charged','Call-Offs','T<5','T5–14','T15+','NCNS','Left Early','Suspended','Doctor Covered','Thresholds','Credits','Focus Signal'],trendRows)}</div><div class="report-section report-allow-break"><h2>Current Period by Shift</h2>${reportTable(['Shift','Active Employees','Point Events','Points Charged','Call-Offs','Tardies','NCNS','Left Early','Suspended','Doctor Covered','Thresholds','Credits','Focus Current','Focus Prior','Signal'],shiftRows)}</div><div class="report-section report-compact"><h2>Selected Period vs Prior Equal-Length Period</h2>${reportTable(['Aggregate Measure','Current','Prior','Change','Signal'],measureRows)}</div>`;
  showReport('Attendance Trend & Risk Report','Aggregate attendance pressure by period, shift, and event type',body,'landscape',autoPrint);
}
