  const codeRows=ATT_POINT_CODES.map(c=>[esc(c.code),esc(c.label),attendancePointDisplayValue(c.code),r30.counts[c.code]||0,selected.counts[c.code]||0]);
  const pointRows=pm.rows.slice().sort((a,b)=>b.snap.activePoints-a.snap.activePoints||a.emp.name.localeCompare(b.emp.name)).map(x=>[esc(x.emp.name),esc(x.emp.shift||''),x.snap.calculatedActivePoints,x.snap.activePoints,x.snap.bank,x.snap.cleanWorkingDays,esc(x.snap.level),x.due?'Notice Due':esc(x.flow.status)]);
