  const score=totalRequired?Math.round((current/totalRequired)*100):100,postM=postReadinessSummaryMetrics(active);
  const shiftRows=Object.entries(active.reduce((m,e)=>{const key=trainingShiftLabel(trainingShiftGroup(e.shift)),r=trainingReadinessForEmployee(e);m[key]=m[key]||{emps:0,total:0,current:0,missing:0,expired:0,expiring:0};m[key].emps++;m[key].total+=r.total;m[key].current+=r.current;m[key].missing+=r.missing;m[key].expired+=r.expired;m[key].expiring+=r.expiring;return m;},{})).map(([shift,x])=>[esc(shift),x.emps,x.total,x.total?Math.round((x.current/x.total)*100)+'%':'100%',x.missing,x.expired,x.expiring]);
  const postRows=trainingPostGroups().map(g=>{let ready=0,issues=0,notReq=0;for(const e of active){const r=postReadinessForEmployee(e,g.key);if(r.status==='Not Required')notReq++;else if(r.status==='Ready')ready++;else issues++;}return[esc(g.label),ready,issues,notReq];});
