function executiveRiskLines(){const m=reportMetrics(),ap=m.attendancePoints,si=siIssueMetrics(),pending=shiftIntelPendingCount(),openTasks=(tasks.tasks||[]).filter(isTaskOpen),overdue=openTasks.filter(isTaskOverdue),lines=[];if(Number(m.cov.total.openHours||0)>0)lines.push(['Staffing',`${m.cov.total.openHours} Open/Pending HPW remain on the published schedule.`,m.cov.total.highestRisk||'Schedule']);if(ap.correctiveDue)lines.push(['Attendance',`${ap.correctiveDue} attendance notice(s) are due; ${ap.atOrAbove9} employee(s) are at the 9+ Final Warning threshold.`,'Notice Control']);else if(ap.atOrAbove6)lines.push(['Attendance',`${ap.atOrAbove6} employee(s) are at or above 6 active attendance points.`,'Point Review']);if(Number(m.training.issueCount||0)>0)lines.push(['Training',`${m.training.issueCount} training readiness exception(s) are open.`,'Training']);if(Number(m.uniformNeeded||0)+Number(m.uniformDueSoon||0)>0)lines.push(['Uniforms',`${m.uniformNeeded} uniform item(s) needed and ${m.uniformDueSoon} replacement-due item(s).`,'Uniform Accountability']);if(si.needs||si.recurring||pending)lines.push(['Shift Intelligence',`${si.needs} Needs Action, ${si.recurring} Recurring, and ${pending} pending intake item(s).`,'Operations']);if(overdue.length)lines.push(['Tasks',`${overdue.length} overdue task(s) need owner follow-up.`,'Task Tracker']);if(!lines.length)lines.push(['Overall','No major open executive exceptions detected from current loaded data.','Monitor']);return lines}
