function governanceNav(active){const items=[['reports','Reports'],['data-health','Data Health'],['restore','Backup & Restore'],['change-log','Change Log'],['settings','Admin Settings']].filter(x=>canAccessModule(x[0]));return `<div class="governance-nav">${items.map(x=>`<button class="${active===x[0]?'active':''}" onclick="navigate('${x[0]}')">${esc(x[1])}</button>`).join('')}</div>`}
function governancePath(labels,activeIndex=0){return `<div class="governance-path">${labels.map((x,i)=>`<div class="governance-step ${i===activeIndex?'active':''}"><strong>Step ${i+1}</strong><span>${esc(x)}</span></div>`).join('')}</div>`}
function reportCatalogItem(id){return REPORT_CATALOG.find(x=>x.id===id)||REPORT_CATALOG[0]}
function reportCategoryOptions(){return ['Recommended'].concat(Array.from(new Set(REPORT_CATALOG.map(x=>x.category))))}
function setReportCenterCategory(category){reportCenterCategory=category;const list=category==='Recommended'?REPORT_CATALOG.filter(x=>x.recommended):REPORT_CATALOG.filter(x=>x.category===category);if(!list.some(x=>x.id===reportCenterSelection))reportCenterSelection=(list[0]||REPORT_CATALOG[0]).id;safeRenderPages({preserveScroll:true})}
function selectReportCenter(id){reportCenterSelection=id;safeRenderPages({preserveScroll:true})}
function reportLibraryHtml(){const list=reportCenterCategory==='Recommended'?REPORT_CATALOG.filter(x=>x.recommended):REPORT_CATALOG.filter(x=>x.category===reportCenterCategory);return `<div class="report-category-filter">${reportCategoryOptions().map(c=>`<button class="${reportCenterCategory===c?'active':''}" onclick="setReportCenterCategory('${escAttr(c)}')">${esc(c)}</button>`).join('')}</div><div class="report-library-list">${list.map(r=>`<button class="report-library-item ${reportCenterSelection===r.id?'active':''}" onclick="selectReportCenter('${r.id}')"><strong>${esc(r.title)}</strong><span>${esc(r.category)}</span></button>`).join('')}</div>`}
function reportGovernanceRail(m,h){const backupState=backupStatusRows?`${backupStatusRows.filter(x=>x.status==='OK').length}/${backupStatusRows.length} checked OK`:'Not checked';return `<div class="governance-rail-card"><strong>Role Visibility</strong><span>${esc(roleOf())} access. Individual pay and cost detail remain Admin-only.</span></div><div class="governance-rail-card"><strong>Data Health</strong><span>${h.critical} critical, ${h.warning} warning, ${h.info} informational finding(s).</span><button class="sm" style="margin-top:8px" onclick="navigate('data-health')">Review Data Health</button></div><div class="governance-rail-card"><strong>Backup Posture</strong><span>${esc(backupState)}</span><button class="sm" style="margin-top:8px" onclick="loadBackupStatusPanel()">Check Backups</button></div><div class="governance-rail-card"><strong>Operating Exposure</strong><span>${m.cov.total.openHours} Open/Pending HPW · ${m.training.issueCount} training issue(s) · ${m.openTasks} open task(s).</span></div>`}
function reportCard(id,title,desc,csv=true,category='Operations',safe='Role-based visibility applies'){return `<div class="report-card"><div class="report-category">${esc(category)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><div class="report-actions"><button class="primary" onclick="viewReport('${id}')">View Report</button><button onclick="printReport('${id}')">Print Report</button>${csv?`<button onclick="exportReportCSV('${id}')">Export CSV</button>`:''}</div><div class="report-safe">${esc(safe)}</div></div>`}
function reportGroup(title,cards){return `<div class="report-group"><div class="report-group-title">${esc(title)}</div><div class="report-card-grid">${cards.join('')}</div></div>`}
function reportOutputActionsHtml(report,selected=false){return `<div class="${selected?'btn-group':'report-actions'} report-output-actions"><button class="primary" onclick="viewReport('${escAttr(report.id)}')">${selected?'Preview Selected Report':'Preview Report'}</button><button onclick="printReport('${escAttr(report.id)}')">Print / Save PDF</button>${report.csv?`<button onclick="exportReportCSV('${escAttr(report.id)}')">Export CSV</button>`:''}</div>`;}
function renderReports(){
  if(!canAccessReports())return `<div class="page-head"><div><div class="page-title">Reports</div><div class="page-sub">Reports are available to Admin and Supervisor roles.</div></div></div><div class="notice warn">Your current role does not have access to Reports.</div>`;
  const m=reportMetrics(),h=computeDataHealth(),r=reportCatalogItem(reportCenterSelection);
  return `<div class="page-head"><div><div class="page-title">Executive Report Center</div><div class="page-sub">Select the management question, confirm scope, preview the output, then publish. Reports no longer compete as a wall of cards.</div></div>${reportOutputActionsHtml(r,true)}</div>${governanceNav('reports')}${governancePath(['Select the report that answers the decision','Confirm reporting period and applicable scope','Preview the finished management output','Print, save PDF, or export CSV'],0)}
  <div class="governance-status-grid"><div class="governance-status"><strong>${m.active.length}</strong><span>Active Headcount</span></div><div class="governance-status"><strong>${m.cov.total.openHours}</strong><span>Open/Pending HPW</span></div><div class="governance-status"><strong>${m.training.issueCount}</strong><span>Training Issues</span></div><div class="governance-status"><strong>${m.openTasks}</strong><span>Open Tasks</span></div><div class="governance-status"><strong>${h.critical}</strong><span>Critical Data Findings</span></div></div>
  <div class="report-center-layout"><section class="report-library"><div class="card-title">Report Library</div>${reportLibraryHtml()}</section><section class="report-detail"><div class="report-detail-head"><div class="chip">${esc(r.category)}</div><h2>${esc(r.title)}</h2><div class="report-note">${esc(r.purpose)}</div></div><div class="report-detail-grid"><div class="report-detail-fact"><strong>Management Decision</strong><span>${esc(r.decision)}</span></div><div class="report-detail-fact"><strong>Source Records</strong><span>${esc(r.source)}</span></div><div class="report-detail-fact"><strong>Audience / Visibility</strong><span>${esc(r.audience)}</span></div><div class="report-detail-fact"><strong>Output</strong><span>Print-ready preview, Save PDF through the print dialog, and CSV export.</span></div></div>${reportStandardControlsHtml(r.id)}${reportScopeRuleHtml(r.id)}${reportOutputActionsHtml(r)}</section><aside class="governance-rail"><div class="card-title">Reporting Readiness</div>${reportGovernanceRail(m,h)}</aside></div>`
}



function defaultSupplyCategories(){return ['Writing','Paper','Printer / Toner','Forms','Binders / Folders','Batteries','Labels / Tape','Breakroom','PPE / Safety','Other']}
function officeSupplyStatus(item){if(item.archived)return 'Archived';const manual=String(item.status||'Auto');if(manual==='Ordered'||manual==='Discontinued')return manual;const q=Number(item.qty||0),min=Number(item.minQty||0);if(q<=0)return 'Out';if(q<=min)return 'Low';return 'In Stock'}
function supplyStatusClass(st){return 'supply-'+String(st||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function supplyStatusBadge(st){return `<span class="supply-status ${supplyStatusClass(st)}">${esc(st)}</span>`}
function supplyRowId(id,field){return 'supply_'+String(id||'new').replace(/[^a-zA-Z0-9_-]/g,'')+'_'+field}
function supplyVal(id,field){let el=document.getElementById(supplyRowId(id,field));return el?el.value:''}
function officeSupplyItems(includeArchived=false){let list=Array.isArray(roster.officeSupplies)?roster.officeSupplies:[];if(!includeArchived)list=list.filter(i=>!i.archived);return list;}
function officeSupplyMetrics(){const all=officeSupplyItems(true);const active=all.filter(i=>!i.archived);const low=active.filter(i=>officeSupplyStatus(i)==='Low').length;const out=active.filter(i=>officeSupplyStatus(i)==='Out').length;const ordered=active.filter(i=>officeSupplyStatus(i)==='Ordered').length;const value=active.reduce((n,i)=>n+(Number(i.cost||0)*Number(i.orderQty||1)),0);return{all,active,low,out,ordered,archived:all.length-active.length,value}}
function supplyCategoryOptions(selected){const cats=Array.from(new Set(defaultSupplyCategories().concat((roster.officeSupplies||[]).map(i=>i.category||'').filter(Boolean))));return cats.map(c=>`<option value="${esc(c)}" ${String(selected)===String(c)?'selected':''}>${esc(c)}</option>`).join('')}
function supplyStatusOptions(selected){return ['Auto','In Stock','Low','Out','Ordered','Discontinued'].map(st=>`<option value="${esc(st)}" ${String(selected||'Auto')===st?'selected':''}>${esc(st)}</option>`).join('')}
function supplyFilterOptions(vals,selected,allLabel){return ['all'].concat(vals).map(v=>`<option value="${esc(v)}" ${String(selected)===String(v)?'selected':''}>${v==='all'?esc(allLabel):esc(v)}</option>`).join('')}
function filteredOfficeSupplies(){let rows=officeSupplyItems(showArchivedSupplies);if(supplySearch){const q=supplySearch.toLowerCase();rows=rows.filter(i=>(String(i.item||'')+' '+String(i.category||'')+' '+String(i.vendor||'')+' '+String(i.location||'')+' '+String(i.notes||'')).toLowerCase().includes(q));}if(supplyCategoryFilter!=='all')rows=rows.filter(i=>String(i.category||'')===String(supplyCategoryFilter));if(supplyStatusFilter!=='all')rows=rows.filter(i=>officeSupplyStatus(i)===supplyStatusFilter);return rows.slice().sort((a,b)=>String(a.archived||false).localeCompare(String(b.archived||false))||String(officeSupplyStatus(a)).localeCompare(String(officeSupplyStatus(b)))||String(a.category||'').localeCompare(String(b.category||''))||String(a.item||'').localeCompare(String(b.item||'')))}
function renderSupplyRow(i){const id=i.id;const st=officeSupplyStatus(i);const archived=!!i.archived;return `<tr class="${archived?'archived-row':''}"><td><input id="${supplyRowId(id,'item')}" value="${esc(i.item||'')}" placeholder="Item name" ${archived?'disabled':''}></td><td><select id="${supplyRowId(id,'category')}" ${archived?'disabled':''}>${supplyCategoryOptions(i.category||'Other')}</select></td><td><input id="${supplyRowId(id,'qty')}" type="number" min="0" step="1" value="${esc(i.qty||0)}" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'minQty')}" type="number" min="0" step="1" value="${esc(i.minQty||0)}" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'orderQty')}" type="number" min="0" step="1" value="${esc(i.orderQty||0)}" ${archived?'disabled':''}></td><td>${supplyStatusBadge(st)}<br><select id="${supplyRowId(id,'status')}" ${archived?'disabled':''}>${supplyStatusOptions(i.status||'Auto')}</select></td><td><input id="${supplyRowId(id,'lastOrdered')}" type="date" value="${esc(i.lastOrdered||'')}" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'lastReceived')}" type="date" value="${esc(i.lastReceived||'')}" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'vendor')}" value="${esc(i.vendor||'')}" placeholder="Vendor" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'location')}" value="${esc(i.location||'')}" placeholder="Storage" ${archived?'disabled':''}></td><td class="admin-pay"><input id="${supplyRowId(id,'cost')}" type="number" min="0" step="0.01" value="${esc(i.cost||'')}" ${archived?'disabled':''}></td><td><input id="${supplyRowId(id,'notes')}" value="${esc(i.notes||'')}" placeholder="Notes" ${archived?'disabled':''}></td><td><div class="supply-actions">${archived?`<button class="sm primary " data-capability="supplies.manage" onclick="restoreOfficeSupply('${esc(id)}')">Restore</button>`:`<button class="sm primary " data-capability="supplies.manage" onclick="saveOfficeSupplyRow('${esc(id)}')">Save</button><button class="sm danger " data-capability="supplies.manage" onclick="removeOfficeSupply('${esc(id)}')">Remove</button>`}</div></td></tr>`}
function openOfficeSupplyModal(){if(!hasCapability('supplies.manage')){toast('Office supply edits are Admin-only');return;}showModal(`<div class="modal-head"><div class="modal-title">Add Office Supply Item</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div class="full"><label>Item Name</label><input id="supplyNewItem" placeholder="Printer paper, toner, clipboards"></div><div><label>Category</label><select id="supplyNewCategory">${supplyCategoryOptions('Other')}</select></div><div><label>Current Quantity</label><input id="supplyNewQty" type="number" min="0" value="0"></div><div><label>Minimum Quantity</label><input id="supplyNewMin" type="number" min="0" value="0"></div><div><label>Order Quantity</label><input id="supplyNewOrder" type="number" min="0" value="0"></div><div><label>Status</label><select id="supplyNewStatus">${supplyStatusOptions('Auto')}</select></div><div><label>Vendor</label><input id="supplyNewVendor"></div><div><label>Storage Location</label><input id="supplyNewLocation"></div><div class="admin-pay"><label>Cost</label><input id="supplyNewCost" type="number" min="0" step="0.01"></div><div class="full"><label>Notes</label><input id="supplyNewNotes"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="addOfficeSupply()">Add Item</button></div>`)}
async function addOfficeSupply(){const name=val('supplyNewItem').trim();if(!name){toast('Item name is required');return;}roster.officeSupplies=Array.isArray(roster.officeSupplies)?roster.officeSupplies:[];const item={id:roster.nextOfficeSupplyId++,item:name,category:val('supplyNewCategory')||'Other',qty:Number(val('supplyNewQty')||0),minQty:Number(val('supplyNewMin')||0),orderQty:Number(val('supplyNewOrder')||0),status:val('supplyNewStatus')||'Auto',vendor:val('supplyNewVendor'),location:val('supplyNewLocation'),cost:Number(val('supplyNewCost')||0),notes:val('supplyNewNotes'),createdAt:new Date().toISOString(),createdBy:currentUserName()||env.user||''};roster.officeSupplies.push(item);roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Office supply item added',detail:name});await saveRosterNow('office-supply-add');closeModal();safeRenderPages();toast('Office supply item added')}
async function saveOfficeSupplyRow(id){if(!hasCapability('supplies.manage')){toast('Office supply edits are Admin-only');return;}let i=(roster.officeSupplies||[]).find(x=>String(x.id)===String(id));if(!i){toast('Supply item not found');return;}const name=supplyVal(id,'item').trim();if(!name){toast('Item name is required');return;}i.item=name;i.category=supplyVal(id,'category')||'Other';i.qty=Number(supplyVal(id,'qty')||0);i.minQty=Number(supplyVal(id,'minQty')||0);i.orderQty=Number(supplyVal(id,'orderQty')||0);i.status=supplyVal(id,'status')||'Auto';i.lastOrdered=supplyVal(id,'lastOrdered');i.lastReceived=supplyVal(id,'lastReceived');i.vendor=supplyVal(id,'vendor');i.location=supplyVal(id,'location');i.cost=Number(supplyVal(id,'cost')||0);i.notes=supplyVal(id,'notes');i.updatedAt=new Date().toISOString();i.updatedBy=currentUserName()||env.user||'';roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Office supply item updated',detail:name});await saveRosterNow('office-supply-save');safeRenderPages({preserveScroll:true});toast('Supply item saved')}
async function removeOfficeSupply(id){if(!hasCapability('supplies.manage')){toast('Office supply removal is Admin-only');return;}let i=(roster.officeSupplies||[]).find(x=>String(x.id)===String(id));if(!i)return;const reason=prompt('Reason for removing/archive this supply item:');if(reason===null)return;if(!String(reason).trim()){toast('Removal reason is required');return;}i.archived=true;i.archivedAt=new Date().toISOString();i.archivedBy=currentUserName()||env.user||'';i.archiveReason=String(reason).trim();roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Office supply item archived',detail:(i.item||'')+' · '+reason});await saveRosterNow('office-supply-remove');safeRenderPages({preserveScroll:true});toast('Supply item archived')}
async function restoreOfficeSupply(id){if(!hasCapability('supplies.manage')){toast('Restore requires supplies.manage');return;}let i=(roster.officeSupplies||[]).find(x=>String(x.id)===String(id));if(!i)return;i.archived=false;i.restoredAt=new Date().toISOString();i.restoredBy=currentUserName()||env.user||'';roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Office supply item restored',detail:i.item||''});await saveRosterNow('office-supply-restore');safeRenderPages({preserveScroll:true});toast('Supply item restored')}
function printOfficeSupplies(){const rows=filteredOfficeSupplies();let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Office Supplies</h2><div>${new Date().toLocaleString()} · low stock, ordered, vendor, and storage location tracker</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><table class="print-table"><thead><tr><th>Item</th><th>Category</th><th>Qty</th><th>Min</th><th>Order Qty</th><th>Status</th><th>Last Ordered</th><th>Last Received</th><th>Vendor</th><th>Location</th><th>Notes</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${esc(i.item)}</td><td>${esc(i.category)}</td><td>${Number(i.qty||0)}</td><td>${Number(i.minQty||0)}</td><td>${Number(i.orderQty||0)}</td><td>${esc(officeSupplyStatus(i))}</td><td>${esc(fmtDate(i.lastOrdered||''))}</td><td>${esc(fmtDate(i.lastReceived||''))}</td><td>${esc(i.vendor||'')}</td><td>${esc(i.location||'')}</td><td>${esc(i.notes||'')}</td></tr>`).join('')||'<tr><td colspan="11">No matching supplies.</td></tr>'}</tbody></table></div>`;document.body.insertAdjacentHTML('beforeend',html);setTimeout(()=>window.print(),150)}
function exportOfficeSuppliesCSV(){const rows=[['Item','Category','Current Qty','Minimum Qty','Order Qty','Status','Last Ordered','Last Received','Vendor','Storage Location','Cost','Notes','Archived','Archive Reason'],...officeSupplyItems(true).map(i=>[i.item||'',i.category||'',i.qty||0,i.minQty||0,i.orderQty||0,officeSupplyStatus(i),i.lastOrdered||'',i.lastReceived||'',i.vendor||'',i.location||'',i.cost||'',i.notes||'',i.archived?'Yes':'No',i.archiveReason||''])];downloadCSV('PWADC_Office_Supplies_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
function renderOfficeSupplies(){const m=officeSupplyMetrics();const cats=Array.from(new Set(defaultSupplyCategories().concat((roster.officeSupplies||[]).map(i=>i.category||'').filter(Boolean))));const sts=['In Stock','Low','Out','Ordered','Discontinued','Archived'];const rows=filteredOfficeSupplies();return `<div class="page-head"><div><div class="page-title">Office Supplies</div><div class="page-sub">Dedicated tracker for office/security supplies. Radios, keys, and uniforms stay in their own trackers.</div></div><div class="btn-group"><button class="primary " data-capability="supplies.manage" onclick="openOfficeSupplyModal()">+ Add Item</button><button onclick="printOfficeSupplies()">Print Supplies</button><button onclick="exportOfficeSuppliesCSV()">Export CSV</button></div></div>${screenGuide('office-supplies')}${renderOperationsWorkflowNav('office-supplies')}<div class="grid cols-5"><div class="kpi"><div class="num">${m.active.length}</div><div class="lbl">Active Items</div></div><div class="kpi"><div class="num schedule-risk">${m.low}</div><div class="lbl">Low Stock</div></div><div class="kpi"><div class="num schedule-risk">${m.out}</div><div class="lbl">Out</div></div><div class="kpi"><div class="num">${m.ordered}</div><div class="lbl">Ordered</div></div><div class="kpi admin-pay"><div class="num" style="font-size:22px">${money(m.value)||'$0.00'}</div><div class="lbl">Est. Reorder Value</div></div></div><div class="card"><div class="supplies-toolbar"><div class="supplies-filters"><div><label>Search</label><input value="${esc(supplySearch)}" placeholder="Item, vendor, location..." oninput="supplySearch=this.value;safeRenderPages()"></div><div><label>Category</label><select onchange="supplyCategoryFilter=this.value;safeRenderPages()">${supplyFilterOptions(cats,supplyCategoryFilter,'All Categories')}</select></div><div><label>Status</label><select onchange="supplyStatusFilter=this.value;safeRenderPages()">${supplyFilterOptions(sts,supplyStatusFilter,'All Statuses')}</select></div><div><label>Archived</label><select onchange="showArchivedSupplies=this.value==='yes';safeRenderPages()"><option value="no" ${!showArchivedSupplies?'selected':''}>Hide Archived</option><option value="yes" ${showArchivedSupplies?'selected':''}>Show Archived</option></select></div></div><div class="notice" style="max-width:420px">Add, edit, remove/archive, restore, print, and export office supplies. Cost fields are Admin-only.</div></div><div class="table-wrap"><table class="wide-table supply-table"><thead><tr><th>Item</th><th>Category</th><th>Qty</th><th>Min</th><th>Order Qty</th><th>Status</th><th>Ordered</th><th>Received</th><th>Vendor</th><th>Storage</th><th class="admin-pay">Cost</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${rows.map(renderSupplyRow).join('')||'<tr><td colspan="13"><div class="empty-state"><strong>No supplies found</strong>Adjust filters or add a new item.</div></td></tr>'}</tbody></table></div></div>`}
function reportOfficeSupplies(autoPrint=false){const active=officeSupplyItems(false),items=reportSupplyItemsForScope(),low=active.filter(i=>officeSupplyStatus(i)==='Low'),out=active.filter(i=>officeSupplyStatus(i)==='Out'),ordered=active.filter(i=>officeSupplyStatus(i)==='Ordered'),value=active.filter(i=>['Low','Out'].includes(officeSupplyStatus(i))).reduce((n,i)=>n+(Number(i.cost||0)*Number(i.orderQty||1)),0);let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> ${items.length} supply record(s) match the selected status scope. Across active inventory, ${low.length} item(s) are low, ${out.length} item(s) are out, and ${ordered.length} item(s) are marked ordered. ${canViewIndividualPay()?'Estimated reorder value for low/out items is '+reportMoney(value)+'.':'Cost detail is restricted to Admin.'}</div></div><div class="report-section">${reportKpis([{label:'Active Items',value:active.length},{label:'Records in Scope',value:items.length},{label:'Low Stock',value:low.length},{label:'Out',value:out.length},{label:'Ordered',value:ordered.length}].concat(canViewIndividualPay()?[{label:'Est. Reorder Value',value:reportMoney(value)}]:[]))}</div><div class="report-section"><h2>Supply Detail</h2>${reportTable(canViewIndividualPay()?['Item','Category','Qty','Min','Order Qty','Status','Vendor','Location','Cost','Notes']:['Item','Category','Qty','Min','Order Qty','Status','Vendor','Location','Notes'],items.map(i=>{const row=[esc(i.item),esc(i.category),Number(i.qty||0),Number(i.minQty||0),Number(i.orderQty||0),supplyStatusBadge(officeSupplyStatus(i)),esc(i.vendor||''),esc(i.location||''),canViewIndividualPay()?reportMoney(Number(i.cost||0)*Number(i.orderQty||1)):'',esc(i.notes||'')];return canViewIndividualPay()?row:row.filter((_,idx)=>idx!==8)}))}</div>`;showReport('Office Supplies Report','Low stock, out-of-stock, ordered items, vendor, and storage location accountability',body,'landscape',autoPrint)}


function moduleInventoryPanel(){
  const activeRoster=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).length;
  const scheduleRows=(roster.schedule||[]).length;
  const trainingTopics=(roster.trainingTopics||[]).filter(t=>t.active!==false).length;
  const trainingRecords=(roster.trainingRecords||[]).length;
  const uniforms=(()=>{try{return (getUniformItems('all')||[]).length}catch(_){return 0}})();
  const supplies=(roster.officeSupplies||[]).filter(i=>!i.archived).length;
  const correctiveActions=(attendance.correctiveActions||[]).length;
  const pointAdjustments=(attendance.pointAdjustments||[]).length;
  const pointPolicyChanges=((attendance.pointSystem&&attendance.pointSystem.pointValueHistory)||[]).length;
  const legacyAttendanceRecords=(attendance.notices||[]).length+Object.keys(attendance.patternActions||{}).length+Object.keys(attendance.flagActions||{}).length;
  const openTasks=(tasks.tasks||[]).filter(t=>String(t.status||'')!=='Archived'&&String(t.status||'')!=='Completed'&&String(t.status||'')!=='Complete').length;
  const openShiftIssues=(shiftReports.issues||[]).filter(i=>['Open','Monitoring'].includes(i.status||'Open')).length;
  const activeIntelIssues=(shiftIntel.issues||[]).filter(i=>!['Resolved','Ignored','Reference Only'].includes(i.status||'New')).length;
  const rows=[
    ['Attendance','attendance-data.json','Employees '+activeAttendanceEmployees().length+' · records '+Object.keys(attendance.attendance||{}).length+' · attendance notices '+correctiveActions+' · point adjustments '+pointAdjustments+' · point policy changes '+pointPolicyChanges+(legacyAttendanceRecords?' · archived legacy records '+legacyAttendanceRecords:'')],
    ['Roster / Schedule','roster-data.json','Active roster '+activeRoster+' · schedule rows '+scheduleRows],
    ['Training','roster-data.json','Active topics '+trainingTopics+' · training records '+trainingRecords],
    ['Uniforms','roster-data.json','Uniform records '+uniforms],
    ['Office Supplies','roster-data.json','Active supply items '+supplies],
    ['Task Tracker','tasks-data.json','Open tasks '+openTasks],
    ['Shift Reports','shift-reports-data.json','Open/monitoring issues '+openShiftIssues+' · imported reports '+((shiftReports.reports||[]).length||0)],
    ['Shift Intelligence','shift-intelligence-data.json','Active issues '+activeIntelIssues+' · intake queue '+((shiftIntel.intake||[]).filter(x=>(x.status||'Pending')==='Pending').length||0)],
    ['Settings / Roles','suite-settings.json','Users '+((settings.users||[]).length||0)+' · Live Schedule is coverage authority'],
    ['Other Programs','Programs folder','Standalone HTML tools copied outside the shared JSON data files']
  ];
  return `<div class="card"><div class="card-title">Module Inventory / Backup Boundaries</div><div class="notice">This pass confirms where each module lives so backup, restore, reports, and Data Health use the same map.</div><div class="table-wrap" style="max-height:none;margin-top:10px"><table><thead><tr><th>Module</th><th>Owned By</th><th>Current Count / Note</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="name"><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join('')}</tbody></table></div></div>`;
}
